    "sections": [
      {
        "id": "overview",
        "heading": null,
        "blocks": [
          {
            "t": "p",
            "c": [
              {
                "t": "text",
                "v": "Ask the Docs and Covenant Brain cite your community's own rules, so they need your documents first."
              }
            ]
          }
        ]
      },
      {
        "id": "steps",
        "heading": "Steps",
        "blocks": [
          {
            "t": "steps",
            "items": [
              [
                {
                  "t": "text",
                  "v": "Open "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "Documents"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": " from the sidebar, then the "
                },
                {
                  "t": "ui",
                  "label": "Governing documents"
                },
                {
                  "t": "text",
                  "v": " tab."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "Give the document a "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "Title"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": " and pick its "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "Document type"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": ", such as Declaration / CC&Rs or Bylaws."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "Choose "
                },
                {
                  "t": "ui",
                  "label": "Upload file"
                },
                {
                  "t": "text",
                  "v": " for a PDF, text or Markdown file, or "
                },
                {
                  "t": "ui",
                  "label": "Paste text"
                },
                {
                  "t": "text",
                  "v": " to paste the words in."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "Select "
                },
                {
                  "t": "ui",
                  "label": "Upload & index"
                },
                {
                  "t": "text",
                  "v": " and wait while it shows "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "Indexing…"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": "."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "To ask a question, open "
                },
                {
                  "t": "ui",
                  "label": "Ask the Docs"
                },
                {
                  "t": "text",
                  "v": " from the sidebar, type your question and select "
                },
                {
                  "t": "ui",
                  "label": "Ask"
                },
                {
                  "t": "text",
                  "v": "."
                }
              ]
            ]
          },
          {
            "t": "shot",
            "name": "guide-documents-governing",
            "alt": "The Governing documents page with the upload form and the Upload & index button highlighted"
          }
        ]
      },
      {
        "id": "what-happens-next",
        "heading": "What happens next",
        "blocks": [
          {
            "t": "p",
            "c": [
              {
                "t": "text",
                "v": "The document appears under "
              },
              {
                "t": "strong",
                "c": [
                  {
                    "t": "text",
                    "v": "Loaded documents"
                  }
                ]
              },
              {
                "t": "text",
                "v": " with the number of sections found and an "
              },
              {
                "t": "strong",
                "c": [
                  {
                    "t": "text",
                    "v": "Indexed"
                  }
                ]
              },
              {
                "t": "text",
                "v": " badge. Ask the Docs can now answer from it, and Covenant Brain can cite it in violation letters."
              }
            ]
          },
          {
            "t": "shot",
            "name": "guide-ask-docs",
            "alt": "The Ask the Docs page with the Ask button highlighted"
          }
        ]
      },
      {
        "id": "if-something-goes-wrong",
        "heading": "If something goes wrong",
        "blocks": [
          {
            "t": "list",
            "items": [
              [
                {
                  "t": "text",
                  "v": "\"We could not extract text from this PDF.\": the PDF is probably a scan. Use "
                },
                {
                  "t": "ui",
                  "label": "Paste text"
                },
                {
                  "t": "text",
                  "v": " instead."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "\"Upload failed\": nothing was saved. Try again in a moment."
                }
              ]
            ]
          }
        ]
      },
      {
        "id": "good-to-know",
        "heading": "Good to know",
        "blocks": [
          {
            "t": "list",
            "items": [
              [
                {
                  "t": "text",
                  "v": "Ask the Docs answers from your documents and names the section it used. When your documents don't cover a question, it is told to say so rather than guess."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "Ask the Docs answers what "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "your rules"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": " say. This Help guide explains "
                },
                {
                  "t": "strong",
                  "c": [
                    {
                      "t": "text",
                      "v": "how to use HomeownerHub"
                    }
                  ]
                },
                {
                  "t": "text",
                  "v": "."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "Scanned PDFs without text can't be read. There is no text recognition."
                }
              ],
              [
                {
                  "t": "text",
                  "v": "You can't open, edit or delete a document from this page yet."
                }
              ]
            ]
          }
        ]
      }
    ],
